//! R-compatible random numbers and R arithmetic semantics (docs/PLAN.md A5; milestone M1).
//!
//! Exact agreement with R depends on copying R's behaviour in a few places. This crate will hold
//! those pieces, each unit-tested against vectors generated by R 4.5.3:
//!
//! - `RRng`: R's Mersenne-Twister stream, including `set.seed`'s initial scrambling and
//!   `unif_rand`'s fixup. One generator is passed explicitly (`&mut RRng`) through every call,
//!   like R's single global stream;
//! - sampling: `R_unif_index` rejection sampling (`sample.kind = "Rejection"`), `sample()` with
//!   and without replacement, weighted sampling without replacement (`revsort`), and `rnorm` by
//!   inversion (`qnorm5`), each consuming exactly as many draws as R;
//! - arithmetic: `round()` half to even, `seq(from, to, by)`, stable `order()`, long-double
//!   `sum()` and `mean()`, two-pass `var()` and `sd()`, and R's 15-significant-digit number
//!   formatting;
//! - R's `fft` (Singleton's mixed-radix algorithm), and OpenBLAS and LAPACK calls through FFI with
//!   the routines and arguments R uses.

pub mod ldouble;
pub mod libm;
pub mod normal;
pub mod rng;
pub mod sample;

pub use ldouble::F80;
pub use normal::{qnorm, rnorm};
pub use rng::RRng;
pub use sample::{sample_int, sample_int_weighted};
